import 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\n\nFuture<void> iShouldSeeASanitizeExportCheckbox(WidgetTester tester) async {\n  // Verify the sanitize export checkbox is present\n  expect(find.byKey(const Key('sanitize_export_checkbox')), findsOneWidget);\n  expect(find.text('Sanitize Export'), findsOneWidget);\n  \n  // Verify it's unchecked by default\n  final checkbox = tester.widget<CheckboxListTile>(find.byKey(const Key('sanitize_export_checkbox')));\n  expect(checkbox.value, isFalse);\n  \n  // Verify explanatory text is present\n  expect(find.text('Remove personal information (names, account numbers, etc.)'), findsOneWidget);\n}